236	    public String getMembershipNumber() {
237	        return this.membershipNumber;
238	    }
239	
240	    public void setMembershipNumber(String membershipNumber) {
241	        this.membershipNumber = membershipNumber;
242	    }
243	
244	    public Boolean getPossibleDuplicate() {
245	        return this.possibleDuplicate;
246	    }
247	
248	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
249	        this.possibleDuplicate = possibleDuplicate;
250	    }
251	
252	    public Integer getPossibleDuplicateOf() {
253	        return this.possibleDuplicateOf;
254	    }
255	
256	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
257	        this.possibleDuplicateOf = possibleDuplicateOf;
258	    }
259	
260	    /**
261	     * Whether this owner has been soft-deleted. A newly created owner is not deleted; the delete
262	     * endpoint flags this true and retains the row rather than removing it. Deleted owners are
263	     * ignored by the create endpoint's duplicate and identity checks.
264	     */
265	    public boolean isDeleted() {
266	        return this.deleted;
267	    }
268	
269	    public void setDeleted(boolean deleted) {
270	        this.deleted = deleted;
271	    }
272	
273	    /**
274	     * The owner's membership points, derived on read: they start at 0, add 2 when an email is
275	     * present, add 1 when {@link #namesakeCount} is 0, add 2 for a household of 3 or more
276	     * ({@link #householdMemberCount}), and add 3 for tenure over one fiscal year (elapsed fiscal
277	     * years from {@link #registrationDate} to today; see {@link #hasTenureBonus(LocalDate)}).
278	     */
279	    @Transient
280	    public Integer getMembershipPoints() {
281	        return membershipPoints(this.email, this.namesakeCount, this.householdMemberCount,
282	            this.registrationDate);
283	    }
284	
285	    /**
286	     * The owner's numeric membership level, derived on read from {@link #getMembershipPoints()}:
287	     * level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more.
288	     */
289	    @Transient
290	    public Integer getMembershipLevel() {
291	        return membershipLevel(getMembershipPoints());
292	    }
293	
294	    /** The membership points derived from the given factors: they start at 0, add 2 when
295	     *  {@code email} is present, add 1 when {@code namesakeCount} is 0, add 2 for a household of 3 or
296	     *  more ({@code householdMemberCount}), and add 3 for sufficient tenure (see
297	     *  {@link #hasTenureBonus(LocalDate)}). */
298	    private static int membershipPoints(String email, Integer namesakeCount,
299	            Integer householdMemberCount, LocalDate registrationDate) {
300	        int points = 0;
301	        if (email != null && !email.isBlank()) {
302	            points += 2;
303	        }
304	        if (namesakeCount != null && namesakeCount == 0) {
305	            points += 1;
306	        }
307	        if (householdMemberCount != null && householdMemberCount >= 3) {
308	            points += 2;
309	        }
310	        if (hasTenureBonus(registrationDate)) {
311	            points += 3;
312	        }
313	        return points;
314	    }
315	
316	    /** Whether the owner's tenure earns the membership tenure bonus: the elapsed fiscal years from
317	     *  {@code registrationDate} to today exceed one, i.e. the registration falls two or more fiscal
318	     *  years before the current one (fiscal years start 1 July). A null registration date earns no
319	     *  bonus. */
320	    private static boolean hasTenureBonus(LocalDate registrationDate) {
321	        return registrationDate != null
322	            && fiscalYear(LocalDate.now()) - fiscalYear(registrationDate) > 1;
323	    }
324	
325	    /**
326	     * The fiscal year (starting 1 July) that contains {@code date}, identified by the calendar year
327	     * in which that fiscal year ends: a date in July-December belongs to the fiscal year ending the
328	     * following calendar year, and a date in January-June to the fiscal year ending that same year
329	     * (e.g. 2026-09-05 -> 2027, 2026-03-01 -> 2026).
330	     */
331	    public static int fiscalYear(LocalDate date) {
332	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
333	    }
334	
335	    /**
336	     * The owner's fiscal year, derived on read from the (business-day-adjusted)
337	     * {@link #registrationDate} as {@code "FY<YY>"}, where YY is the last two digits of the fiscal
338	     * year (starting 1 July) that contains the registration date (e.g. a date of 2026-09-05 yields
339	     * {@code "FY27"}). Returns {@code null} when no registration date is available.
340	     */
341	    @Transient
342	    public String getFiscalYear() {
343	        if (this.registrationDate == null) {
344	            return null;
345	        }
346	        return String.format("FY%02d", fiscalYear(this.registrationDate) % 100);
347	    }
348	
349	    /** The numeric membership level (1-4) mapped from membership points: 1 for 0-1 points, 2 for
350	     *  2-3, 3 for 4-5, and 4 for 6 or more. */
351	    private static int membershipLevel(int points) {
352	        if (points >= 6) {
353	            return 4;
354	        }
355	        if (points >= 4) {
356	            return 3;
357	        }
358	        if (points >= 2) {
359	            return 2;
360	        }
361	        return 1;
362	    }
363	
364	    /**
365	     * The owner's preferred contact channel, derived on read: {@code "EMAIL"} when an email is
366	     * present, otherwise {@code "PHONE"}.
367	     */
368	    @Transient
369	    public String getContactPreference() {
370	        return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
371	    }
372	
373	    /**
374	     * The owner's age band, derived on read from the {@link #birthDate} relative to the
375	     * {@link #registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"} from 18 to 64, and
376	     * {@code "SENIOR"} at 65 or over. Returns {@code null} when no birth date (or no registration
377	     * date to measure against) is available.
378	     */
379	    @Transient
380	    public String getAgeBand() {
381	        if (this.birthDate == null || this.registrationDate == null) {
382	            return null;
383	        }
384	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
385	        if (age < 18) {
386	            return "MINOR";
387	        }
388	        if (age < 65) {
389	            return "ADULT";
390	        }
391	        return "SENIOR";
392	    }
393	
394	    /**
395	     * The single Luhn check digit (0-9) computed over the decimal digits contained in the
396	     * {@link #customerCode}, derived on read.
397	     */
398	    @Transient
399	    public Integer getCheckDigit() {
400	        return luhnCheckDigit(this.customerCode);
401	    }
402	
403	    /** Region -> inclusive 4-digit postcode range {low, high}, used to derive the region from the
404	     *  postcode ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
405	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
406	        "NSW", new int[] {2000, 2099},
407	        "VIC", new int[] {3000, 3099},
408	        "QLD", new int[] {4000, 4099});
409	
410	    /**
411	     * The owner's region, derived on read. The postcode is preferred: a 4-digit postcode falling in a
412	     * known region's range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}) yields
413	     * that region. When the postcode is absent or in no known range, it falls back to the fixed
414	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}).
415	     * Returns {@code "UNKNOWN"} when neither source resolves a region.
416	     */
417	    @Transient
418	    public String getRegion() {
419	        String byPostcode = regionForPostcode(this.postcode);
420	        if (byPostcode != null) {
421	            return byPostcode;
422	        }
423	        if ("Sydney".equals(this.city)) {
424	            return "NSW";
425	        }
426	        if ("Melbourne".equals(this.city)) {
427	            return "VIC";
428	        }
429	        if ("Brisbane".equals(this.city)) {
430	            return "QLD";
431	        }
432	        return "UNKNOWN";
433	    }
434	
435	    /**
436	     * The owner's locality, derived on read from the region-and-hash {@link #getCustomerCode()
437	     * customer code}: the region segment before the first '-' of the customer code
438	     * ('<REGION>-<HASH8>'). Falls back to the owner's {@link #getRegion() region} when no customer
439	     * code has been assigned yet.
440	     */
441	    @Transient
442	    public String getLocality() {
443	        if (this.customerCode != null) {
444	            int dash = this.customerCode.indexOf('-');
445	            if (dash > 0) {
446	                return this.customerCode.substring(0, dash);
447	            }
448	        }
449	        return getRegion();
450	    }
451	
452	    /** Region -> IANA timezone name, the fixed region-to-timezone table ({@code NSW ->
453	     *  Australia/Sydney}, {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}). */
454	    private static final Map<String, String> REGION_TIMEZONES = Map.of(
455	        "NSW", "Australia/Sydney",
456	        "VIC", "Australia/Melbourne",
457	        "QLD", "Australia/Brisbane");
458	
459	    /**
460	     * The owner's timezone, derived on read as the IANA name for the owner's
461	     * {@link #getLocality() locality/region} via the fixed region-to-timezone table
462	     * ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
463	     * {@code QLD -> Australia/Brisbane}). Returns {@code null} when the region carries no entry in
464	     * the table (e.g. {@code UNKNOWN}).
465	     */
466	    @Transient
467	    public String getTimezone() {
468	        return timezoneForRegion(getLocality());
469	    }
470	
471	    /** The IANA timezone name for {@code region} via the fixed region-to-timezone table, or
472	     *  {@code null} when the region carries no entry ({@code NSW -> Australia/Sydney},
473	     *  {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}). */
474	    public static String timezoneForRegion(String region) {
475	        return REGION_TIMEZONES.get(region);
476	    }
477	
478	    /** The inclusive 4-digit postcode {@code {low, high}} range for {@code region}, or {@code null} when
479	     *  the region carries no range rule (i.e. {@code UNKNOWN} or any region absent from the table:
480	     *  {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
481	    public static int[] postcodeRangeForRegion(String region) {
482	        return REGION_POSTCODE_RANGES.get(region);
483	    }
484	
485	    /** The region whose postcode range contains {@code postcode}, or {@code null} when the postcode is
486	     *  absent, not a 4-digit value, or in no known range. */
487	    private static String regionForPostcode(String postcode) {
488	        if (postcode == null || !postcode.matches("^[0-9]{4}$")) {
489	            return null;
490	        }
491	        int value = Integer.parseInt(postcode);
492	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
493	            int[] range = entry.getValue();
494	            if (value >= range[0] && value <= range[1]) {
495	                return entry.getKey();
496	            }
497	        }
498	        return null;
499	    }
500	
501	    /** Telephone country code -> the national-number length it requires ({@code +61} Australia => 9
502	     *  digits, {@code +1} NANP => 10), used to derive telephone values from the stored E.164 number.
503	     *  The country codes here carry no conflicting prefixes ({@code +61} does not start with
504	     *  {@code +1}), so a number matches at most one. */
505	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
506	        "+61", 9, "+1", 10);
507	
508	    /**
509	     * The stored E.164 {@link #telephone} formatted for humans, derived on read: the country code, a
510	     * space, then the national digits grouped in threes (e.g. {@code "+61 412 345 678"}). Falls back
511	     * to the raw value when it is {@code null} or begins with no recognised country code.
512	     */
513	    @Transient
514	    public String getTelephoneDisplay() {
515	        if (this.telephone == null) {
516	            return null;
517	        }
518	        String countryCode = countryCodeOf(this.telephone);
519	        if (countryCode == null) {
520	            return this.telephone;
521	        }
522	        String national = this.telephone.substring(countryCode.length());
523	        StringBuilder grouped = new StringBuilder(countryCode);
524	        for (int i = 0; i < national.length(); i++) {
525	            if (i % 3 == 0) {
526	                grouped.append(' ');
527	            }
528	            grouped.append(national.charAt(i));
529	        }
530	        return grouped.toString();
531	    }
532	
533	    /** The recognised telephone country code that {@code telephone} begins with (e.g. {@code "+61"}),
534	     *  or {@code null} when it is {@code null} or begins with no recognised country code. */
535	    public static String countryCodeOf(String telephone) {
536	        if (telephone == null) {
537	            return null;
538	        }
539	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet()) {
540	            if (telephone.startsWith(countryCode)) {
541	                return countryCode;
542	            }
543	        }
544	        return null;
545	    }
546	
547	    /** The national-number length required for {@code countryCode}, or {@code null} when the country
548	     *  code carries no length rule (i.e. any code absent from the table: {@code +61 => 9},
549	     *  {@code +1 => 10}). */
550	    public static Integer nationalNumberLength(String countryCode) {
551	        return NATIONAL_NUMBER_LENGTHS.get(countryCode);
552	    }
553	
554	    /** The single Luhn check digit (0-9) over the decimal digits contained in {@code value}, scanning
555	     *  right to left and doubling every second digit; non-digit characters are ignored and a null or
556	     *  digit-free value yields {@code 0}. */
557	    private static int luhnCheckDigit(String value) {
558	        int sum = 0;
559	        boolean doubling = true;
560	        for (int i = (value == null ? 0 : value.length()) - 1; i >= 0; i--) {
561	            char c = value.charAt(i);
562	            if (c < '0' || c > '9') {
563	                continue;
564	            }
565	            int digit = c - '0';
566	            if (doubling) {
567	                digit *= 2;
568	                if (digit > 9) {
569	                    digit -= 9;
570	                }
571	            }
572	            sum += digit;
573	            doubling = !doubling;
574	        }
575	        return (10 - (sum % 10)) % 10;
576	    }
577	
578	    protected Set<Pet> getPetsInternal() {
579	        if (this.pets == null) {
580	            this.pets = new HashSet<>();
581	        }
582	        return this.pets;
583	    }
584	
585	    protected void setPetsInternal(Set<Pet> pets) {
586	        this.pets = pets;
587	    }
588	
589	    public List<Pet> getPets() {
590	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
591	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
592	        return Collections.unmodifiableList(sortedPets);
593	    }
594	
595	    public void setPets(List<Pet> pets) {
596	        this.pets = new HashSet<>(pets);
597	    }
598	
599	    public void addPet(Pet pet) {
600	        getPetsInternal().add(pet);
601	        pet.setOwner(this);
602	    }
603	
604	    /**
605	     * Return the Pet with the given name, or null if none found for this Owner.
606	     *
607	     * @param name to test
608	     * @return true if pet name is already in use
609	     */
610	    public Pet getPet(String name) {
611	        return getPet(name, false);
612	    }
613	
614	    /**
615	     * Return the Pet with the given name, or null if none found for this Owner.
616	     *
617	     * @param name to test
618	     * @return true if pet name is already in use
619	     */
620	    public Pet getPet(String name, boolean ignoreNew) {
621	        name = name.toLowerCase();
622	        for (Pet pet : getPetsInternal()) {
623	            if (!ignoreNew || !pet.isNew()) {
624	                String compName = pet.getName();
625	                compName = compName.toLowerCase();
626	                if (compName.equals(name)) {
627	                    return pet;
628	                }
629	            }
630	        }
631	        return null;
632	    }
633	
634	    public Pet getPet(Integer petId) {
635	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
636	    }
637	
638	    @Override
639	    public String toString() {
640	        return new ToStringCreator(this)
641	
642	            .append("id", this.getId())
643	            .append("new", this.isNew())
644	            .append("lastName", this.getLastName())
645	            .append("firstName", this.getFirstName())
646	            .append("address", this.address)
647	            .append("city", this.city)
648	            .append("telephone", this.telephone)
649	            .toString();
650	    }
651	}
