605	    /**
606	     * The effective registration date to store for a new owner: the date supplied on the request
607	     * when present, otherwise the current server date, in either case rolled forward to a business
608	     * day so it never falls on a weekend or public holiday (rolled forward to the next such day).
609	     * This single point of resolution is what every registration-date-derived value (the stored
610	     * date, the membership number's year segment, the per-day create-limit) is computed from.
611	     */
612	    private static LocalDate resolveRegistrationDate(LocalDate suppliedDate) {
613	        LocalDate date = suppliedDate != null ? suppliedDate : LocalDate.now();
614	        return toBusinessDay(date);
615	    }
616	
617	    /**
618	     * The fixed list of public holidays that a registration date must not fall on. A date landing
619	     * on one of these is rolled forward, exactly as weekends are.
620	     */
621	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
622	        LocalDate.of(2026, 1, 1),
623	        LocalDate.of(2026, 1, 26),
624	        LocalDate.of(2026, 4, 25),
625	        LocalDate.of(2026, 12, 25),
626	        LocalDate.of(2026, 12, 28));
627	
628	    /**
629	     * Roll {@code date} forward to the next business day: a Saturday, Sunday, or listed public
630	     * holiday is advanced day by day until it lands on a non-holiday weekday, which is returned
631	     * unchanged.
632	     */
633	    private static LocalDate toBusinessDay(LocalDate date) {
634	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY
635	                || PUBLIC_HOLIDAYS.contains(date)) {
636	            date = date.plusDays(1);
637	        }
638	        return date;
639	    }
640	
641	    /**
642	     * Build the membership number '<customerCode>-M<YY>' where YY is the
643	     * {@link #membershipYearSegment(LocalDate) fiscal-year segment} of the {@code registrationDate}
644	     * (e.g. 'NSW-1A2B3C4D-M27').
645	     */
646	    private static String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
647	        return customerCode + "-M" + membershipYearSegment(registrationDate);
648	    }
649	
650	    /**
651	     * The two-digit year segment stamped into a membership number: the last two digits of the
652	     * fiscal year (starting 1 July) that contains the business-day-adjusted {@code registrationDate},
653	     * zero-padded (e.g. a date of 2026-09-05 falls in fiscal year 2027 -> '27'). Shares the
654	     * fiscal-year rule with {@link Owner#getFiscalYear()} via {@link Owner#fiscalYear(LocalDate)}.
655	     */
656	    private static String membershipYearSegment(LocalDate registrationDate) {
657	        return String.format("%02d", Owner.fiscalYear(registrationDate) % 100);
658	    }
659	
660	    /**
661	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
662	     * last name, compared case-insensitively.
663	     */
664	    private int countNamesakes(Owner owner) {
665	        String firstName = normalizeHouseholdField(owner.getFirstName());
666	        String lastName = normalizeHouseholdField(owner.getLastName());
667	        return (int) this.clinicService.findAllOwners().stream()
668	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
669	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
670	            .count();
671	    }
672	
673	    /**
674	     * Whether more than 80 owners have already been created today, i.e. carry today's (business-day
675	     * resolved) registration date. Surfaced on responses as {@code bulkSignupWarning} to flag an
676	     * unusually high daily signup volume.
677	     */
678	    private boolean isBulkSignupWarning() {
679	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > 80;
680	    }
681	
682	    /** The number of existing owners whose registration date is {@code date}. */
683	    private int countOwnersRegisteredOn(LocalDate date) {
684	        return (int) this.clinicService.findAllOwners().stream()
685	            .filter(existing -> date.equals(existing.getRegistrationDate()))
686	            .count();
687	    }
688	
689	    /**
690	     * The single derived key all duplicate detection flows through, formed from the owner's
691	     * already-normalized fields as {@code normalizedTelephone + '|' + (email or empty) + '|' +
692	     * (householdId or empty)}. It is computed at the create-time identity gate, before the household
693	     * id is derived, so the household segment is empty at that point. Because the telephone is part
694	     * of the key, two owners in the same household with different telephones resolve to different
695	     * keys and are both allowed.
696	     */
697	    private static String identityKey(Owner owner) {
698	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
699	        String email = owner.getEmail() == null ? "" : owner.getEmail();
700	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
701	        return telephone + "|" + email + "|" + household;
702	    }
703	
704	    /**
705	     * Whether {@code owner}'s whole {@link #identityKey} equals an existing owner's, which is the sole
706	     * duplicate condition: the previously separate telephone, email and household checks are now all
707	     * expressed through this one key, so only an exact full-key match is a duplicate and a create that
708	     * trips it is rejected with {@code 409 CONFLICT}.
709	     */
710	    private boolean isDuplicate(Owner owner) {
711	        String key = owner.getIdentityKey();
712	        return this.clinicService.findAllOwners().stream()
713	            .filter(existing -> !existing.isDeleted())
714	            .map(Owner::getIdentityKey)
715	            .filter(existing -> existing != null)
716	            .anyMatch(key::equals);
717	    }
718	
719	    /** Common street-type abbreviations expanded during address normalization. */
720	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
721	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
722	
723	    /**
724	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
725	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
726	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
727	     * string when {@code address} is null or blank after normalization.
728	     */
729	    private static String normalizeAddress(String address) {
730	        if (address == null) {
731	            return "";
732	        }
733	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
734	        if (collapsed.isEmpty()) {
735	            return "";
736	        }
737	        StringBuilder sb = new StringBuilder(collapsed.length());
738	        for (String token : collapsed.split(" ")) {
739	            if (sb.length() > 0) {
740	                sb.append(' ');
741	            }
742	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
743	        }
744	        return sb.toString();
745	    }
746	
747	    /**
748	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
749	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
750	     */
751	    private static String normalizeHouseholdField(String value) {
752	        if (value == null) {
753	            return "";
754	        }
755	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
756	    }
757	
758	    /**
759	     * Existing owners that share {@code owner}'s household, i.e. resolve to the same
760	     * {@link #householdId(Owner) householdId}. Household membership is defined by that single derived
761	     * key rather than re-derived from the underlying fields here, so the household is described in one
762	     * place and every household-keyed value stays consistent with it.
763	     */
764	    private List<Owner> findHousemates(Owner owner) {
765	        String householdId = householdId(owner);
766	        return this.clinicService.findAllOwners().stream()
767	            .filter(existing -> !existing.isDeleted())
768	            .filter(existing -> householdId(existing).equals(householdId))
769	            .toList();
770	    }
771	
772	    /**
773	     * The number of owners in {@code owner}'s household once this owner is created, i.e. the existing
774	     * housemates (owners sharing the same {@code householdId}) plus {@code owner} itself.
775	     */
776	    private int countHouseholdMembers(Owner owner) {
777	        return findHousemates(owner).size() + 1;
778	    }
779	
780	    /**
781	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
782	     * same last name (compared case-insensitively with collapsed whitespace) and postcode. It is the
783	     * first 12 hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode} (the empty
784	     * string standing in for a missing postcode), so housemates always resolve to the same value
785	     * regardless of registration order, and owners sharing a last name and postcode share it
786	     * automatically.
787	     */
788	    private static String householdId(Owner owner) {
789	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
790	        String key = normalizeHouseholdField(owner.getLastName()) + "|" + postcode;
791	        return sha256Hex(key).substring(0, 12);
792	    }
793	
794	    /** The upper-case hex SHA-256 of the UTF-8 bytes of {@code input}, as 64 hex characters. */
795	    private static String sha256Hex(String input) {
796	        try {
797	            byte[] digest = MessageDigest.getInstance("SHA-256")
798	                .digest(input.getBytes(StandardCharsets.UTF_8));
799	            StringBuilder sb = new StringBuilder(digest.length * 2);
800	            for (byte b : digest) {
801	                sb.append(String.format("%02X", b));
802	            }
803	            return sb.toString();
804	        }
805	        catch (NoSuchAlgorithmException e) {
806	            throw new IllegalStateException("SHA-256 not available", e);
807	        }
808	    }
809	}
